quests[54080] = { id = 54080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54082] = { id = 54082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Power", description = "Welcome back, dear test subject.\n\nMy dear sister has kindly asked me to administer today's experiment, which falls below our typical standards of legality...\n\nYou may, as always, choose not to participate and we will acquire sufficient replacement test subjects.\n\nOur new project requires more energy than our generator can manage. We must supercharge it with a jolt of power from the outside.\n\nBondo's Yard has the best power line in Mechagon, so we shall siphon what we need from those rapscallions.", completion = "Our generator is bristling with power... I've never felt so alive!", objectives = "Connect power lines from Bondo's Yard to the Quickcharge laboratory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54083] = { id = 54083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grease The Wheels", description = "Kerchunk said you guys was working on getting that mechaspider running again. Well I'm not gonna let you have all the fun!\n\nThat rusty old thing's gonna need a lot of grease to get moving again. So I jury-rigged a special Grease Trap to help you gather grease from the slimes nearby.", completion = "That was greasy work, glad it wasn't me doing it!", objectives = "Use the Grease Trap to collect 12 Cog Grease from slimes around The Outflow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54085] = { id = 54085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Accessories Sold Separately" }
quests[54086] = { id = 54086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Bot for the Job", description = "We don't waste anything around here. Every defeated bot gets a second chance! \n\nIf I'm going to fix this mechaspider, I'm going to need a few extra wrenchbots working with me. \n\nUse my Bot Re-Energizer on three dead Repeating Wrenchbots and bring them to me, and I'll put them to work.", progress = "Did you find those Repeating Wrenchbots yet?", completion = "These bots will work round the clock fixing this mount!", objectives = "Bring three Repeating Wrenchbots to Recycler Kerchunk", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54087] = { id = 54087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Must be This Height", description = "The moment is here {name}. \n\nFor such a historic moment I feel a gnome, such as myself, should be the one to activate the device.\n\nLet me know when you think we should begin.", progress = "This is quite an important discovery!", completion = "I'm sure the king didn't mean any harm to YOU champion. Please don't let this incident deter you. I need your help!", objectives = "Let me know when I can activate the device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54088] = { id = 54088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Mechagon", description = "I came as soon as I heard!  A mysterious vault has been discovered in Tiragarde. \n\nCenturies ago, the last king of the gnomes, King Mechagon, led his followers in search of a mythical land of technology. He left no clue as to where he was headed, and over time his legend faded into history. This vault could be the first step to discovering King Mechagon's true fate! \n\nI must examine it firsthand. Meet me there, Champion. I could use your assistance.", completion = "It's as promising as I had hoped! Now that you're here we shall begin the investigation.", objectives = "Meet Tinkmaster Overspark outside the mysterious vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54089] = { id = 54089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omgar Doombow" }
quests[54090] = { id = 54090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toys For Destruction", description = "Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research.\n\nI had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em!\n\nHelp me wrangle everyone's ideas into one perfect weapon!", progress = "You build an amazing weapon yet?", completion = "Something as beautiful as that, needs to be put to good use!", objectives = "Help Rocket-Chief Fuselage build the perfect weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54091] = { id = 54091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strong Arm John" }
quests[54094] = { id = 54094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Goblin's Definition of Success", description = "I'm all set here, I'm just gonna play around with the mech, I think I got a good idea how it works thanks to ya.\n\nNathanos \"prince of all that's death and destruction\" Blightcaller is gonna want you back on that boat, the Banshee's Scream or whatever it is.\n\nHe'll be happy to know we took care of business. Then again, I got no idea if he even feels happy anymore.", completion = "Good work. We can breath a little easier knowing our major supply of Azerite is safe.\n\nThe Dark Lady has further plans that will require your aid. We have a promising lead on someone who can help us destroy Kul Tiras from within.\n\nKeep up the fight against the Alliance in the meantime. We cannot afford to let down our guard.", objectives = "Meet with Nathanos on the Banshee's Wail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54096] = { id = 54096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of the Sunwell", description = "The flame of the lantern dims. Your final task is to rekindle it.\n\nIn order to do so, you must walk one remaining path. While we are fortunate to hold the Sunwell once again, we must always remember that it was yet another part of us that Arthas took away... and that our late prince was forced to find us a new way of life.\n\nEnter the Sunwell Plateau, and witness its fall.", completion = "<The Regent Lord takes the lantern from you.>\n \nIt is done.", objectives = "Complete the Fall of the Sunwell scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54097] = { id = 54097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Lady Calls", description = "Champion, the Dark Lady has need of you.\n\nWe cannot speak more of this here. Make haste to Orgrimmar at once.\n\nBest not to keep her waiting.", completion = "My guards are stationed at the door to ensure that this meeting stays private.\n\nNow, let us discuss Varok Saurfang.", objectives = "Meet with Lady Sylvanas Windrunner in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54099] = { id = 54099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Overlord", description = "I have asked you here to discuss a matter of great importance to the Horde.\n\nVarok Saurfang is no longer in Stormwind.\n\nLet us discuss this turn of events.", progress = "I trust your discretion in this matter.", completion = "I hope you understand how grave of a situation this is, champion.\n\nThe Alliance will surely kill him on sight. Some members of the Horde consider him a traitor for his willing surrender at the Battle for Lordaeron.\n\nIf Varok Saurfang is to make it back to us alive, it will be up to you. Be discreet.", objectives = "Discuss Saurfang's fate with Lady Sylvanas Windrunner in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54100] = { id = 54100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Way Out", description = "My spies report that our High Overlord did not leave the way he entered, nor any other way we know of. No signs of him were seen at any of the known exits from the Stockades or the sewers. He simply was in his cell one moment, and gone the next.\n\nBegin your investigation around the city of Stormwind. There must be another way out that we do not know of.\n\nDark Ranger Lyana will meet you there. Her tracking skills are second to none.\n\nDo not fail me, my champion.", completion = "There is no time to waste. Let us begin our investigation.", objectives = "Meet with Dark Ranger Lyana in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54101] = { id = 54101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Track", description = "Keep your head down. We do not want to be seen out here.\n\nOur spies keep watch over Stormwind day and night, and saw no signs of Saurfang. \n\nNor did we notice any oddly-oversized carts or strange ships in the night, if that was what you were thinking.\n\nHow then, did he make his escape?\n\nLet's look around.", progress = "Let us keep investigating.", completion = "SI:7 lurking around Stormwind? Hmm, probably after the same thing we are.\n\nWe need to keep moving.", objectives = "Follow the trail of Varok Saurfang in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54102] = { id = 54102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastern Escape", description = "It's not unusual to see SI:7 spies lurking around the city, but something about this doesn't feel right.\n\nWe need to find where Saurfang's trail picks up. The last tracks were heading east, towards Redridge.\n\nThe path to Redridge crosses the Three Corners, one of the Alliance's more well-defended towers.\n\nI have an idea. Meet me there.", completion = "There are few paths through Redridge, save this one.\n\nWe should start the next stage of our investigation here.", objectives = "Meet Dark Ranger Lyana at Three Corners in Redridge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54103] = { id = 54103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corner Crossing", description = "If Saurfang was headed in this direction, it would have been difficult for him to avoid the Three Corners watchpost. \n\nWe could simply walk in there and demand information, but I have a feeling that they would not part with it willingly.\n\nSo we will take another approach.\n\nI have procured this potion from our alchemists. It will turn us into--ugh--humans for a while.\n\nWe can then question the guards. Perhaps someone saw something.", progress = "Let's find out everything we can.", completion = "So, Shaw was involved? SI:7... again.\n\nPerhaps a coincidence, perhaps not. \n\nWe have little to go off of. Let us assume Saurfang continued his path eastward, off of the main trails.", objectives = "Drink the Humanizing Potion, then question the citizens of Redridge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54104] = { id = 54104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Saurfang", description = "With the guards drunk at their posts, and others out of position, Saurfang would have had little trouble passing Three Corners undetected.\n\nThe path splits just south of town. The back roads of Redridge are poorly patrolled, and are infested with gnolls and spiders. In other words, perfect for an orc trying not to be noticed.\n\nHis most likely path is Lakeridge Highway. We should continue our investigation there.", progress = "Well? What are you waiting for?", completion = "Well, that was invigorating. \n\nBased on the size of that spider and how injured it was, I'd venture a guess that we are on the right track.\n\nAnd I think I know where to head next.", objectives = "Follow the trail of Varok Saurfang in Redridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54105] = { id = 54105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ever Eastward", description = "All signs point to our quarry heading farther east. \n\nTo what end, I am not sure. But I have my suspicions.\n\nI am going to scout the area from the air. Let's meet up at Redridge Pass.", completion = "This is one of the few pathways through the Redridge Mountains. If Saurfang came this direction, it was through this pass.", objectives = "Find Dark Ranger Lyana at Redridge Pass in Redridge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54106] = { id = 54106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Tipoff", description = "Look there, down the hill. One of the Alliance hunters that roam the area.\n\nNo one knows these pathways like them. If our quarry passed through here, that hunter would certainly have seen the tracks. His dogs may even have caught Saurfang's scent.\n\nHere is another dose of the potion. Let us question this one while he is alone.", progress = "Let's find out everything we can.", completion = "Thank you for your assistance in this investigation, champion. We have all but confirmed Saurfang's current location.\n\nI must report back to the warchief before we make any further moves. We will summon you if we require your assistance again.", objectives = "Drink the Humanizing Potion, then question Hunter McAlister at Redridge Pass in Redridge Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54107] = { id = 54107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Tidings", description = "Ey mon, dat dark ranger, she be lyin' to ya!\n\nSaurfang knew dey'd be comin' for him. He sent me to watch da pass, see who his assassins be. Try to warn him if I could.\n\nShe not be reportin' back nothin'... she gonna kill him. Most likely got a whole buncha deathguards just waitin' for her signal.\n\nWe gotta stop dem! Ya wit' me?", completion = "It be too late! Dey beat us here!", objectives = "Meet with Zekhan in Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54108] = { id = 54108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warrior's Death", description = "She gonna try an' take him in, and den no one ever gonna see Varok Saurfang again.\n\nDis was never a rescue mission. Dis be about power, an' control, an' Sylvanas think she be holdin' all da cards.\n\nBut she didn't count on us!\n\nLet's go!", progress = "Will you stand with us?", completion = "I thank you and young Zekhan for your assistance. I knew she would come for me. It was only a matter of time. \n\nAnd I do not think she will give up.\n\nNow I have something I must ask of you.", objectives = "Defend Varok Saurfang in Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54109] = { id = 54109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Queen's Favor", description = "I have two things to ask of you, and I do not ask them lightly.\n\nFirst, I need you to retain the favor of the warchief. She will undoubtedly have questions, and seeds of distrust may begin to grow, but she cannot lose you as an ally. Not now. She would not so willingly part with one of her greatest champions.\n\nIn order to do so, it will have to look like you faced me in combat, and lost. I trust you can take a hit.\n\nSecond, I ask you not to follow me further. I must make this journey alone.", completion = "I have not heard back from Lyana since I sent her on her last mission.\n\nAre you here to complete her report?", objectives = "Take a hit from Varok Saurfang, then report to Warchief Sylvanas Windrunner in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54112] = { id = 54112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistweaver Nian" }
quests[54113] = { id = 54113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.>", completion = "Ah... much better. How cruel of that priest to leave me in such a state!\n\nBut enough about me. No doubt you have many questions. I can offer countless answers.", objectives = "Assist Xal'atath in recovering its strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54114] = { id = 54114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.\n\nIt is a familiar sensation.>", completion = "Ah... much better. How cruel of you to leave me in such a state!\n\nBut we can reminisce later. No doubt you have many questions. As you know, I can offer countless answers.", objectives = "Assist Xal'atath in recovering its strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54117] = { id = 54117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.>", completion = "Ah... much better. How cruel of that priest to leave me in such a state!\n\nBut enough about me. No doubt you have many questions. I can offer countless answers.", objectives = "Assist Xal'atath in recovering its strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54118] = { id = 54118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.\n\nIt is a familiar sensation.>", completion = "Ah... much better. How cruel of you to leave me in such a state!\n\nBut we can reminisce later. No doubt you have many questions. As you know, I can offer countless answers.", objectives = "Assist Xal'atath in recovering its strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54119] = { id = 54119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hartford Sternbach" }
quests[54120] = { id = 54120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Orgrimmar", description = "A darkness in me mind be keeping me from remembering what happened da day I named Sylvanas warchief.\n\nTake me glaive and travel to da pyre where I was cremated in Orgrimmar.\n\nMaster Gadrin be packin' enough juju to call me to dat place.\n\nGo, and I be seein' ya dere.", completion = "Vol'jin might be havin' confidence in me skill, but I asked some allies to come aid us. Dis not be an easy task. Talanji be da better choice for such a ritual, but I will do me best.", objectives = "Take the Glaive of Vol'jin to Master Gadrin at Drannosh'ar Blockade, Durotar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54121] = { id = 54121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Out Ashvane", description = "The Dark Lady wishes to gain another potential ally in the fight against the Alliance.\n\nLady Ashvane, head of the Ashvane Company, was one of the greatest enemies of Kul Tiras until her capture.\n\nWe are going to release her.\n\nMeet Valtrois in Tiragarde Sound. She and Rexxar are working out a plan to break Ashvane out.", completion = "Your arrival is timely. We have much to do.", objectives = "Meet Valtrois in Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54123] = { id = 54123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Belongs in My Mech!", description = "Check this out! It's my latest creation that someone else came up with and built, Gallywix's Mech of Death!\n\nI got it fueled with all that Azerite you found, but I still need more of the stuff to give it that extra kick.\n\nI was SUPPOSED to have the stuff from our operations here, but there's some sorta Azerite goop causin' a mess!\n\nMy guy Patch made an Azerite vacuum device. I want you to suck the Azerite outta these slimes!", completion = "That's what I'm talkin' about! This bad boy is gonna be fueled up in no time.", objectives = "Recover Azerite from Azerite slimes using the Azerite Vacuumizer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54124] = { id = 54124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avoiding Lawsuits 101", description = "Yo, {name}! I leave the A.M.O.D. for two seconds to deal with old Gallywix and now I'm knee-deep in Azerite goo!\n\nListen, here's the deal. I need ya to rescue some of these goblins from these monsters.\n\nI'll be honest, I skimped on the money that covers their insurance in the event of Azerite-monster-related injuries.\n\nWhat? Who knew that these slimes would appear and attack these guys!\n\nDo me a solid and get these goblins outta there!", progress = "Ya help those guys?", completion = "You're a real life saver! Well, life for them, gold for me.\n\nIf anyone asks, we never talked about this. Ya catching my drift?", objectives = "Rescue 6 Uninsured Goblin Workers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54126] = { id = 54126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twist the Knife", description = "The relics are ours... as it was meant to be.\n\nThere is but one more step needed for the great truths to be revealed.\n\nThe naga sought to summon their storm from a place that echoes with ancient power. Though this site has had countless names over the ages, you mortals know it as the Precipice of Oblivion.\n\nI will go on ahead and begin preparations. Join me there.", completion = "<Brother Pike listens to your tale of Xal'atath and N'Zoth.>\n\nDark tidings indeed, {name}.\n\nI could sense something stirring beneath the waves. If the Old God is on the rise, we must make ready.", objectives = "Meet Xal'atath at the Precipice of Oblivion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54127] = { id = 54127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Hop", description = "Horde forces are attacking Tiragarde Sound. Make them regret every footstep upon our soil!", objectives = "Repel the Hordes forces attacking Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54128] = { id = 54128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necessary Precautions", description = "That was freakin' awesome! We decimated Mekkatorque's puny little army.\n\nWe got a location on where that little punk and his airship is. That's where he's controllin' all his FORMER mechs.\n\nHere's the plan, we're gonna fly over there, blow up that freak, then destroy his airship!\n\nNow, I ain't no idiot, {name}, I'm the smartest goblin alive. First, we gotta take what they call necessary precautions.\n\nTake this manual, I want you to make sure the G.M.O.D is ready to go!", progress = "Well? This thing ain't gonna double check itself! Although... maybe it should.", completion = "I don't care what the meter says, I say we're good to go!", objectives = "Review the G.M.O.D's systems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54129] = { id = 54129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Mate Malone" }
quests[54130] = { id = 54130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our New Friends", description = "I heard that the Alliance is growing! More and more different kinds of people are joining all the time to fight the mean Horde.\n\nI'm not sure where the embassy is, but I heard it's somewhere here in Stormwind. Can you show me how to get there? I want to see all our new friends!", progress = "I bet all of our new friends came from really far away!", completion = "We have so many new friends in the city now! I hope they'll play with me!", objectives = "Take your Human Orphan to the Stormwind Embassy. If your orphan is not present when you arrive, call for him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54132] = { id = 54132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde of Heroes", description = "The Alliance has begun a coordinated assault against our forces in Stormsong Valley. Attack the enemy forces and drive them back!", completion = "I heard Usha spoke highly of your actions in Stormsong in her report... You must have done well, because she hates everyone!", objectives = "Lead the Horde assault into Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54134] = { id = 54134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Many Fine Heroes", description = "The Alliance has the upper hand in Vol'dun.  We strike now!  You will lead our forces to victory!", progress = "Have we pushed the Horde out of Vol'dun?", completion = "I wish I could've seen that final battle in Vol'dun myself! I heard it was incredible... If we had more soldiers like you, this war would be over tomorrow.", objectives = "Lead the Alliance assault into Vol'dun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54135] = { id = 54135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Romp in the Swamp", description = "Alliance armies are landing on the shores of Nazmir. Drive them back to the sea. Zandalar is ours!", progress = "Nazmir belongs to the Zandalari, and the Horde!", completion = "Thank you, {name}. We cannot allow anyone to take dis land from us.\n\nNot de blood trolls. Not de Alliance. Not any outsiders.\n\nDis land belong to de Zandalari... and de Horde. Forever.", objectives = "Repel the Alliance forces assaulting Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54136] = { id = 54136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March on the Marsh", description = "The Alliance has begun a coordinated assault against the Horde in Nazmir. Defeat the enemy forces and drive them out!", progress = "What news do you bring from the front lines of Drustvar?", completion = "Nazmir may not look like much, but every territory we control opens up strategic options for the future.\n\nPlus, I hear you made quite a dent in the Horde's fleet out there. Ha! That alone was worth the trip.", objectives = "Lead the Alliance assault into Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54137] = { id = 54137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Every Dark Corner", description = "The Alliance's hold on Drustvar is weak. We will conquer it for the Horde!", progress = "What news do you bring from the front lines of Drustvar?", completion = "Wherever the Alliance hides... we will find them.\n\nI'm glad Rokhan and the Darkspear are on our side.", objectives = "Lead the Horde assault into Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54138] = { id = 54138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Rampage", description = "The Alliance has launched an assault into the very heart of the Zandalari empire. Defeat the Horde on their own soil to show them our strength!", completion = "I read Magister Umbric's report... It sounded like quite an impressive display over there. The Horde must know now that we can control powers far beyond theirs.", objectives = "Lead the Alliance assault into Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54139] = { id = 54139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Is Here", description = "We need to move, {name}. We've received word that the Alliance have mounted an attack through Nazmir.\n\nMake for the Great Seal. King Rastakhan and Princess Talanji are there forming a plan of attack.\n\nMake no mistake, we will crush the Alliance. They are fools to attack us through Nazmir.", progress = "Let's get moving.", completion = "Let us move, we do not have time.", objectives = "Meet King Rastakhan within the Great Seal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54140] = { id = 54140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride of the Zandalari", description = "It is time de Alliance see de full fury of de Zandalari. Dey are fools to try an attack in Nazmir.\n\nWe must tell de fleet, our warriors, and our flyers dat dey must move out and go to Nazmir at once.\n\nI will go aid our forces at de Blood Gate. Here is a list of dose you must speak with to mobilize our forces.\n\nMove as fast as you can, we must stop de Alliance as quickly as possible.", completion = "The Zandalari and Horde are engaging the Alliance. We must move!", objectives = "Mobilize the Zandalari fleet, warriors, and flyers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54141] = { id = 54141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azsharan Medallion", description = "<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue.\n\nPerhaps someone with a knowledge of naga artifacts could translate the text.>", completion = "A medallion, you say? Well, let's have a look at it.\n\nI don't have all day, you know.", objectives = "Take the Medallion to Collector Kojo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54143] = { id = 54143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bird's-Eye View" }
quests[54144] = { id = 54144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from Azshara", description = "<Kojo studies the medallion and grimaces.>\n\nUgh... naga.\n\nThis medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power.\n\nYou know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me.\n\nI found it on an island in Stormsong Valley, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.", progress = "<As you place the dagger upon the altar, it seems to shudder and blink at you.>", completion = "<You are filled with a sense of dread and foreboding.\n\nThis is probably a very bad idea.>", objectives = "Take the Dagger to the Makeshift Altar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54145] = { id = 54145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Loa of Death", description = "Bwonsamdi is a dangerous loa, but even I do not believe he whispered to Vol'jin on his deathbed. To appoint Sylvanas sounds, well... he is not fond of de undead. And from what I have seen of de warchief, she is no fan of death.\n\nWe must be respectful when we speak to Bwonsamdi, or dere will be consequences. Come, stay close.", completion = "Now listen here, mon. Usually, ya disrespectul actions would be mighty irritatin' to Ol' Bwonsamdi. But I be lettin' dis one slide. For now.\n\nWhat ya be talkin' about sounds like some bad mojo. I gonna need ya to find out more from some of me... \"old friends.\"", objectives = "Confront Bwonsamdi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54146] = { id = 54146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strong New Allies", description = "I heard some adventurers saying that there are new members of the Horde, unlike all the rest! And the best part? They're right here in Orgrimmar!\n\nI don't know where the embassy is... but I bet you do! Can you take me? I heard there are orcs from another planet!", progress = "New friends in Orgrimmar! That means I can come back and visit them all the time.", completion = "Our new friends are so cool! I can't wait to come back and visit all the time.", objectives = "Take your Orcish Orphan to the Orgrimmar Embassy. If your orphan is not present when you arrive, call for him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54147] = { id = 54147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confront The Val'kyr", description = "Vol'jin's spirit is growing in power. I should no longer have to maintain a ritual to keep him here.\n\nDis is fortunate, since Bwonsamdi warned me dat Eyir will likely not be pleased with my presence. Apparently she and Bwonsamdi have a past de loa was unwilling to discuss.\n\nWe can proceed when you are ready.", completion = "Ah... Eyir. Lots of anger and pride in dat one. She not be speakin' ta me for centuries now. I thought for sure she be da one behind Vol'jin's return.", objectives = "Escort the Spirit of Vol'jin to Eyir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54154] = { id = 54154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hills Have Spies" }
quests[54156] = { id = 54156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Path of Blood", description = "De main fleet of de Alliance and Kul Tirans are off de coast in Nazmir. But we cannot ignore de forces here.\n\nDere seems to be a strange fog coming in from Nazmir. De Kul Tirans must be using some of their voodoo to weaken us.\n\nWe must carve a path of blood through dese Alliance fools. Help our forces by weakening de Alliance.", completion = "Good, my forces can handle de remnants. You need to keep moving.", objectives = "Slay 15 Alliance soldiers within the Blood Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54157] = { id = 54157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No One Left Behind", description = "De warriors here tell me Rokhan made a heroic stand, holding off de Alliance and their champions before being defeated.\n\nRokhan is still here within de Blood Gate, held captive by some strange creature called a Lightforged.\n\nI must stay here and help hold de line. I need you to rescue Rokhan!", completion = "Thank you, {name}. Rokhan will prove valuable in our fight against de Alliance.", objectives = "Rescue Rokhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54161] = { id = 54161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Drust Knew", description = "Bal'a dash, {name}.\n\nIf you have a moment, I could use your assistance. I've recently received a shipment of Drust relics that were smuggled out of Kul Tiras.\n\nMost have our usual enchantments, but there is one that is unique. Just holding it makes my hair stand on end. \n\nWith you being my best pupil, I was thinking that it would be enlightening if we disenchanted it together, to see how it was made.\n\nWhat do you say?", completion = "I'm sorry, {name}, I didn't think that the enchantment would be so complex. I thought I could maintain the incantation.\n\n\n\nI guess that's it. With the relic destroyed the technique behind its construction is lost.\n\nA shame, really. It's not often that I'm left dumbfounded by another enchanter.", objectives = "Carefully remove the enchantment from the Ancient Drust relic to learn about its construction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54162] = { id = 54162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard Landing" }
quests[54163] = { id = 54163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As the Dust Settles", description = "We have achieved a great victory, {name}, though at a cost.\n\nKing Wrynn is gathering the Alliance leadership in Unity Square to discuss matters. He has requested our presence as well. \n\nGo to Unity Square. I'll meet you there shortly.", completion = "Thank you for coming, {name}.", objectives = "Meet with Anduin Wrynn in Unity Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54164] = { id = 54164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The King's Death", description = "King Rastakhan is dead, the Zandalari fleet has been decimated, and we have lost valuable soldiers.\n\nThe Dark Lady is on her way from Orgrimmar to assess the situation. We must figure out our next move before the Alliance strike again.\n\nI believe protocol now would be to pay respects to the fallen king. We will determine our next move afterwards.", completion = "Good, you're all here. Let's begin our discussions.", objectives = "Pay respects to King Rastakhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54165] = { id = 54165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Return of Derek Proudmoore", description = "I'll admit, I did not think the Little Lion had it in him to kill King Rastakhan. Blood has been spilled, and vengeance must be had.\n\nGive me a moment to express my condolences, then come with me. We have more to do to win this war.", completion = "Derek Proudmoore will be twisted to become a weapon against Katherine and Jaina Proudmoore.\n\nThe Allliance brought an army to kill Rastakhan. All we'll need is one Forsaken to kill their leaders.\n\nI will contact you when your aid is further needed. In the meantime, continue the fight against the Alliance, we must survive until this plan is ready.", objectives = "Observe Sylvanas's discussion with Princess Talanji.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54166] = { id = 54166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set Sail", description = "Assist the Horde by collecting Azerite on Island Expeditions.", objectives = "Collect Azerite on Island Expeditions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54167] = { id = 54167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set Sail", description = "Assist the Alliance by collecting Azerite on Island Expeditions.", objectives = "Collect Azerite on Island Expeditions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54169] = { id = 54169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Treasury Heist", description = "The Abyssal Scepter is a powerful tidesage artifact and a serious threat to the fleet. The Horde stole it, but it is being held by the Zandalari in their treasury.\n\nThe Storm's Wake has crafted a fake Scepter. Your first job is to obtain the real one without alerting suspicion.\n\nSpeak to me when you are ready to go over the plan.", progress = "Were you successful?", completion = "Mission accomplished on all fronts, it seems. I will ensure that the High Tinker gets the data you collected.\n\nI remember hearing stories of the Abyssal Scepter when I was young. Aside from being a tactical victory, it is good to have this relic back in our hands. Thank you.", objectives = "Retrieve the Abyssal Scepter from the Zandalari Treasury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54170] = { id = 54170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormin Rocketbop" }
quests[54171] = { id = 54171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abyssal Scepter", description = "The Lord Admiral has proposed our next move. It's something we don't think the Horde will expect, but it's dangerous: We're going to steal back the Abyssal Scepter.\n\nYour name came up as someone who could see it through, if you're willing to take the chance.\n\nMeet Lady Jaina at our base in Xibala. She'll have more information for you there.", completion = "<Jaina looks up from her consultation with Magister Umbric as you approach.>\n\nThis mission will be dangerous, but it's necessary to ensure our victory here in Zandalar.", objectives = "Meet with Jaina Proudmoore in Xibala in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54172] = { id = 54172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azsharan Medallion", description = "<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue.\n\nPerhaps someone with a knowledge of naga artifacts could translate the text.>", completion = "A medallion, you say? Well, let's have a look at it.\n\nI don't have all day, you know.", objectives = "Take the Medallion to Collector Kojo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54174] = { id = 54174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from Azshara", description = "<Kojo studies the medallion and grimaces.>\n\nUgh... naga.\n\nThis medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power.\n\nYou know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me.\n\nI found it nearby at Atal'Gral, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.", progress = "<As you place the dagger upon the altar, it seems to shudder and blink at you.>", completion = "<You are filled with a sense of dread and foreboding.\n\nThis is probably a very bad idea.>", objectives = "Take the Dagger to the Makeshift Altar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54175] = { id = 54175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Face Your Enemy", description = "We have decided that our best course of action would be to enter the prison disguised as Proudmoore military. Rexxar will be our prisoner.\n\nWe want to keep a low profile until we break Ashvane out.\n\nI find that I work better with reference when undertaking this type of endeavor.\n\nI have chosen some humans that interest me. I would like to examine their faces.\n\nUse the Shard of Vesara on them, and they will be... encouraged to find their way to me.", completion = "Humans can be so malleable.", objectives = "Send the targets chosen by Valtrois back for examination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54176] = { id = 54176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be More Uniform", description = "Head into the foundry. Proudmoore's guards have taken over there. They will provide excellent accessories for our disguises.\n\nI can recreate their faces, but without the clothing, we won't make it far.\n\nGather enough gear to cover us. \n\nWe'll need the Captain's jacket as well. \n\nThere will be less of a challenge at the gate if we outrank them.", progress = "Was the harvest successful?", completion = "Well done, {name}. This is going better than I expected.", objectives = "Collect gear from Proudmoore forces in the foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54177] = { id = 54177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brilliant Distraction", description = "We plan to be cautious on entry to Tol Dagor.\n\nI imagine our exit will not be as... subtle.\n\nThat foundry to the west... I hear they made Azerite explosives there.\n\nStock up, we will need them.", progress = "Did you find them all?", completion = "Gently...\n\nMaybe Valtrois should take charge of these. She may be able to stabilize them another way.", objectives = "Retrieve the Volatile Azerite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54178] = { id = 54178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching a Ride", description = "Nathanos should have found a boat by now.\n\nLet us hasten to meet him in the harbor.\n\nIt behooves us to take care of this business quickly.\n\nThere are better ways for us to support the Horde's effort here.", completion = "This should be adequate.", objectives = "Find Nathanos at the dock in Plunder Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54179] = { id = 54179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Front Door", description = "We would like the least amount of risk during your retrieval of Priscilla Ashvane.\n\nYou will arrive on the docks during a shift change. From there, you will prepare and enter the prison. \n\nFind me in Zuldazar when you are successful.", completion = "Your success bodes well for our future endeavors.", objectives = "Complete \"Escape from Tol Dagor\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54180] = { id = 54180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest" }
quests[54182] = { id = 54182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilgewater Bash Brothers" }
quests[54183] = { id = 54183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Reckoning", description = "While I have some concerns, I cannot deny the bravery, heroism and sacrifices we have made. That you have made, {name}. Thank you for all the aid you have given to the Alliance.\n\nThe future of our ongoing war campaign is why I have asked everyone here. I wish to look at what we've done, so we can decide on the best way forward.", progress = "This war may have been necessary, but it is my hope it will be over soon. Then we can begin rebuilding.", completion = "We may be on the cusp of winning but we cannot lose sight of ourselves or we will have lost what is most important and our victories will be for nothing.\n\nI hope it will be as High Commander Wyrmbane and Master Shaw say it is and we will see a conclusion soon. Then... Then we can begin the process of rebuilding and healing - Ourselves as well as Azeroth and the Horde.", objectives = "Attend the discussion in Unity Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54184] = { id = 54184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in Gnomeregan", description = "Some strange spikes of electric usage have been happening in Gnomeregan recently. We need you to investigate what is going in there as soon as possible.\n\nWe've received contact from one of the chief engineers in charge of keeping things in Gnomeregan under control, and he has offered to assist us in getting inside to see what's going on.", completion = "I don't know how this is possible! What is going on in there?! I don't have time to answer your questions or send you off on trivial tasks, there's work to be done! \n\nOh, you want to go in Gnomeregan and find out what's going on? Why didn't you say so?", objectives = "Find Micro Zoox outside of Gnomeregan in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54185] = { id = 54185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeregan's New Guardians", description = "My personally-modified Mayhem Detection Device has been giving readings off the charts for the last few days. You might be thinking that mayhem and Gnomeregan are synonymous, and to an extent they are, but these readings are beyond anything I've seen before!\n\nI'm not totally sure what's going on inside of Gnomeregan, but something is different. If you are feeling brave enough, I can teleport you deep in there and you can see for yourself.\n\nLet me know when you are ready.", progress = "I can teleport you in. Getting out might be more of a challenge.", completion = "Someone stole a schematic from one of Thermaplugg's inventions?  This isn't good, we've heard that a mischievous group has been collecting odd parts from the Wailing Caverns and the Deadmines as well. What crazy thing could they be doing? Who is this group? We better start finding some answers, and soon.", objectives = "Defeat Pulverizer Bot Mk 6001 in Gnomeregan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54186] = { id = 54186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battle Challenge: Gnomeregan", description = "Gnomeregan's at Mayhem Level Maximum again. Those machines just don't give up, and keep coming back.\n\nI can teleport us in there again, but all of those crazy robots are back. You sure you want this? I don't.  I mean, maybe I want to watch robots smash things for some entertainment.  I'm sure you will be fine. Lets go!", progress = "I can teleport you in. Getting out might be more of a challenge.", completion = "Someone stole a schematic from one of Thermaplugg's inventions?  This isn't good, we've heard that a mischievous group has been collecting odd parts from the Wailing Caverns and the Deadmines as well. What crazy thing could they be doing? Who is this group? We better start finding some answers, and soon.", objectives = "Defeat Pulverizer Bot Mk 6001 in Gnomeregan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54187] = { id = 54187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tea for Two" }
quests[54188] = { id = 54188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrambled Bots" }
quests[54189] = { id = 54189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Crawl" }
quests[54190] = { id = 54190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tea for Two" }
quests[54191] = { id = 54191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing Course", description = "Champion, the time for action is upon us. \n\nDevelopments are underway that will change the course of this war. \n\nReport to me aboard Wind's Redemption as soon as possible.", completion = "I have news from our allies.", objectives = "Report to Halford Wyrmbane aboard Wind's Redemption in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54192] = { id = 54192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sensitive Intel", description = "I've received a report from Kelsey Steelspark. She claims to have discovered something that will aid our war effort.\n\nShe's refused to go into specifics, citing a need for secrecy with such sensitive intel.\n\nIt looks like you'll need to speak to her in person. \n\nShe's expecting you in Xibala.", completion = "Take a moment to prepare yourself. I've got huge news!", objectives = "Meet Kelsey Steelspark in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54193] = { id = 54193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This is Huge!", progress = "Wait until you hear their big plan. It's perfect!", completion = "All up to speed, then?", objectives = "Listen to Megs and Morton's plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54194] = { id = 54194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Real Big Power", description = "We're still building a harness for the Embiggifier, but we need to test its core first. That's where the real power is!\n\nThis technology is years ahead of the Horde's, but it's so easy to use that even an orc could do it!\n\nJust point and click!", progress = "I love this part! When we get to see all our hard work pay off in a big way!", completion = "I thought that might happen. \n\nThat poor clucker's mind wasn't strong enough to withstand the Embiggifier, but otherwise, it's working as intended!", objectives = "Test the Embiggifier on a Kul Tiran Clucker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54195] = { id = 54195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Beast with Brains", description = "For optimal results, the Embiggifier should be used on someone with substantial intellect. \n\nGood thing our partner is as smart as they come. \n\nHe and his kind have been empowered by kaja'mite, granting them exceptional intelligence! \n\nHead up to the gorge and let Grong know we're ready to begin the embiggifying!", completion = "So the time has finally come! \n\nI have been awaiting this day--the day my ideas would be brought to life!\n\nBut first, I must see that the gorge will be safe after my departure.", objectives = "Find Grong within Gorilla Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54196] = { id = 54196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Options", progress = "It pains me to descend to their level, but I fear I've exhausted all other options.", completion = "It's a shame we had to resort to violence, but I believe this was the only way.", objectives = "Kill 12 Bilgewater goblins within Gorilla Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54197] = { id = 54197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freedom for the Da'kani", description = "Have you seen the barbaric conditions to which the Da'kani are subjected? Corralled and caged, awaiting slaughter, or worse...\n\nI cannot leave here in good faith without first seeing that my kind are liberated.", completion = "You are a true friend of the Da'kani.", objectives = "Free 8 Da'kani Highbrows within Gorilla Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54198] = { id = 54198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittersweet Goodbyes", description = "You've helped me prepare my village for my departure, but now I must prepare myself. \n\nMeet me within the grotto, where I will say my farewells.", completion = "I am ready.", objectives = "Meet Grong within Grong's Grotto.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54199] = { id = 54199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Needs of the Many", completion = "You don't disappoint, {name}. Grong is the answer to all our problems.\n\nI'll just need him to sign a few dozen documents before we get started. All standard stuff, I assure you.", objectives = "Accompany Grong to Xibala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54200] = { id = 54200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Base", description = "We'll need to collect some baseline statistics before we use the Embiggifier.\n\nGrong will be asked to perform basic tasks pertaining to speed, intelligence, and strength. \n\nThis will help us measure the increase once he's been embiggified.", completion = "Quite impressive, really! Grong's in superb condition.", objectives = "Help collect baseline stats for Grong's speed, intelligence, and strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54201] = { id = 54201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fit for Grong", description = "Grong is already impressively large. In fact, I don't think our Embiggifier is going to fit around his noggin without some modification. \n\nI'll require an ample supply of ore to make the necessary adjustments, but we're in luck. The goblins nearby have already done the work of mining it; we just need to take it off their hands!\n\nSecure an ample amount of Azerite-infused ore, and we'll be back in business!", progress = "Have you acquired the ore?", completion = "This should help ensure the Embiggifier is a perfect fit!", objectives = "Collect 12 Azerite Infused Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54202] = { id = 54202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calibrate the Core", description = "The Embiggifier is nearly ready! All that's left to do is calibrate its core. \n\nThe best way to do that without catastrophic results is to use it on things that are already dead.\n\nThis should be a simple task!\n\nI have a hunch you excel at making things dead.", progress = "Have you calibrated the core yet?", completion = "The calibration is complete? Splendid!", objectives = "Calibrate the Embiggifier's core by using it on dead things within Bilgewater Bonanza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54203] = { id = 54203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Embiggining", description = "I'll give you the quick rundown before we get started.\n\nThe Embiggifier is remotely controlled. \n\nSee this big red button?\n\n<Megs gestures to the device in her hand.> \n\nThis jolts the wearer with a surge of power, making them bigger.\n\nFor safety reasons, you should remain here at camp. \n\nI think that's it! Are you ready to science?", progress = "Let's see what Grong can do once he's been embiggified!", completion = "Grong exceeded all our expectations. I'd say this is a resounding success.", objectives = "Test Grong's stats while embiggified.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54204] = { id = 54204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total Temple Destruction", description = "Grong is our greatest achievement, and he's ready to be unleashed!\n\nThe Horde is staging its troops at a temple to the north. \n\nMagister Umbric's portal will get you there fast. Then Grong can get to work!", completion = "I'm not sure how I feel, {name}. \n\nThe Embiggifier worked, but Grong won't ever be the same.\n\nI suppose it's what he wanted, and what we need if we hope to win this war.", objectives = "Command Grong to defeat the Horde at Temple of the Prophet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54205] = { id = 54205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nice Nap", description = "I'm not sure how much longer those chains will hold. \n\nGrong's going to have to take a little nap until he's ready to be deployed.\n\nUse this dart. It's been double-dipped in something potent enough to take down a direhorn, so it should do the trick. \n\nGrong would want you to be the one to do it.", progress = "Go ahead, use the dart on Grong. He won't feel a thing, I promise.", completion = "Grong will go down in history as a true hero of the Alliance.", objectives = "Use the Tranquilizer Dart on Grong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54206] = { id = 54206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sleeper Agent", completion = "Are you certain about this? Our secret weapon is a gorilla? \n\nI suppose I'll just have to trust that the gnomes know what they're doing. \n\nThank you for your report, {name}.", objectives = "Report back to Halford Wyrmbane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54207] = { id = 54207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retaking the Outpost", description = "We can handle de rest of de Alliance. I received a report that Hexlord Raal's forces are having issues up ahead.\n\nHe claims dat dere is an even thicker fog enveloping Nazmir. De Alliance must be using some tricks to slow us down.\n\nGo to Nazmir to see what can be done to help Hexlord Raal. We must reach dat fleet and destroy de Alliance!", completion = "I wish I had better news to tell you and Princess Talanji.", objectives = "Meet Hexlord Raal in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54208] = { id = 54208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minesweeper", description = "The Alliance are stalling our efforts here with this irritating fog, as well as layering the entire area with traps.\n\nWe will suffer too many casualties if we try marching our army through this trap-infested area.\n\nI've heard you're good at sneaking around. Use your talents to disarm the traps in this area.\n\nI'll deal with getting the goblin's parts back from the Alliance while you disarm those traps.", completion = "Good, we should be able to march our army now. Rokhan and I recovered enough parts for these goblins to rebuild their machine.", objectives = "Disarm 10 traps within the Fallen Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54211] = { id = 54211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting the Gob in Gob Squad", description = "Yo! We gotta get the rest of the Gob Squad back if we wanna fix the A.F.M.O.D.!\n\nSo, our mech got trashed. It was rough. The rest of the Gob Squad are hidin' out there, waiting for word when it's safe.\n\nTake this tracker. It'll tell ya when you're getting close to one of the squad. When you get real close, you should see 'em.\n\nThat'll tell any of the squad nearby that it's safe to come outta hidin' and come back here.\n\nWith the right goblins and parts, we'll be killing Alliance in no time!", progress = "You didn't blow up the Gob Squad tracker, did you?", completion = "I gotta tell ya, it feels good to get the gang back.", objectives = "Rescue the Gob Squad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54212] = { id = 54212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-rebuilding the A.F.M.O.D.", description = "Alright, so, we're goin' after the Alliance through this crazy fog. We gotta retake Zo'bal ruins up ahead.\n\nWe can do that real easy if we fix up our mech, A.F.M.O.D. - a flying mech of death! \n\nThe Alliance wrecked it in their initial attack and took a bunch of its parts. Get those parts back and we'll have this thing fixed in no time!", progress = "You got the parts? We'll figure out what goes where when it's all done.", completion = "Great! We'll get this thing fixed in no time.", objectives = "Recover 10 A.F.M.O.D. parts from Gilnean Ambushers and Night Elf Sentinels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54213] = { id = 54213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Alive!", description = "We got the A.F.M.O.D. repaired and it works perfectly! Eh, except that it's got no power.\n\nPrincess Talanji seems like she can help us out with this. Ask her if she can give the mech a jumpstart!\n\nOnce we're set, we can use this thing to mow down the Alliance, take back Zul'jan ruins, and push forward to blow up that fleet!", progress = "Uh, can we get this thing started or what?", completion = "Hahaha! Now it's time to show these guys how we roll.", objectives = "Speak with Talanji to power up the A.F.M.O.D.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54224] = { id = 54224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Zul'jan Ruins", description = "General Rakera has pushed forward with de army. Raal and his forces are still grounded until we remove dis fog.\n\nYou must pilot de A.F.M.O.D. and help our forces retake Zul'jan ruins. Only den can we move ahead to stop de Alliance and dis fog.\n\nRokhan, and I will join you. De Alliance must see dat our victory is swift and decisive. \n\nI would have our enemies cower before us when dey meet dere ends. Such is de price for defiling our lands.", completion = "De last time I was in Zul'jan, we had an army cobbled together from our allies in Nazmir.\n\nNow, we have de full force of my empire and de Horde. Let us march forward!", objectives = "Pilot the A.F.M.O.D. and retake Zul'jan ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54225] = { id = 54225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: The Great Seal", description = "Your followers have sent a report regarding the mission at The Great Seal.\n\nIt details that the mission was a success and that a Mission Command Table has been constructed.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission to The Great Seal?", completion = "It seems the mission at The Great Seal was a success. Well done, {name}.", objectives = "Deliver the mission report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54231] = { id = 54231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outpost Upgrade: The Great Seal", description = "The mission at The Great Seal was a success. Well done, {name}.\n\nA Mission Command Table is now ready for use.\n\nTravel to The Great Seal and see that the troops quality of work is up to our standard.", objectives = "Inspect the Mission Command Table at The Great Seal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54236] = { id = 54236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Attack!" }
quests[54237] = { id = 54237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Togoth Cruelarm" }
quests[54239] = { id = 54239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Zul'jan Ruins", description = "Your followers have sent a report regarding the mission at Zul'jan Ruins.\n\nIt details that the mission was a success and that the power of the Loa has increased, allowing for Boons to persist longer.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission to Zul'jan Ruins?", completion = "It seems the mission at Zul'jan Ruins was a success. Well done, {name}.", objectives = "Deliver the mission report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54240] = { id = 54240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outpost Upgrade: Zul'jan Ruins", description = "The mission at Zul'jan Ruins was a success. Well done, {name}.\n\nThe Boons of the Loa are now more powerful and will be granted whenever you are in Zandalar.\n\nTravel to the Zul'jan Ruins and honor an altar of your choice.", objectives = "Choose a Loa Boon from the altars at Zul'jan Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54243] = { id = 54243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobliteration" }
quests[54244] = { id = 54244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have Them Cornered", description = "General Rakera has already begun mobilizing our forces to our next target: Zalamar.\n\nOnce we destroy de Alliance dere, we can push forward to de coast and destroy de source of dis fog.\n\nDe Alliance will have nowhere to hide. We will surround their fleet and end dis war, once for all.\n\nDey will wish dey never stepped foot in Nazmir.\n\nCome. We shall ride together to Zalamar and ensure our victory!", progress = "We must move!", completion = "We have de Alliance forces cornered. We must finish dem off.", objectives = "Ride with Princess Talanji and Rokhan to Zalamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54245] = { id = 54245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Altercation" }
quests[54246] = { id = 54246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Altercation" }
quests[54249] = { id = 54249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zandalari Justice", description = "We must wipe out whatever is left of de Alliance in Zalamar. Den we can find de source of dis fog and dere fleet.\n\nRokhan will scout ahead to find dis Telaamon. He appears to be de general leading de forces here.\n\nI need you to go in and wipe out de Alliance forces within Zalamar so dat we can crush dem once and for all.\n\nFind Rokhan in Zalamar after dey have been weakened.", progress = "We must keep up de pressure on de Alliance.", completion = "I be dealin' with de Alliance down here. I woulda thought dey be bringin' more soldiers ta de party.", objectives = "Defeat 15 Alliance forces within Zalamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54251] = { id = 54251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ambassador" }
