quests[54257] = { id = 54257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Greensails" }
quests[54258] = { id = 54258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Vulpera Hideaway", description = "Your followers have sent a report regarding the mission at the Vulpera Hideaway.\n\nIt details that the mission was a success and that a Caravan is now available for use.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission to Vulpera Hideaway?", completion = "It seems the mission at Vulpera Hideaway was a success. Well done, {name}.", objectives = "Deliver the mission report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54260] = { id = 54260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outpost Upgrade: Vulpera Hideaway", description = "The mission at Vulpera Hideaway was a success. Well done, {name}.\n\nThe Caravan Master is very thankful for our assistance and ready to return the favor.\n\nTravel to Vulpera Hideaway and speak with the Caravan Master to see what he can do for you.", completion = "You better believe I'm glad to be out of the hands of the Faithless! Thank you so much!\n\nIf you ever need to ride in a Caravan, you be sure to let me know. \n\nIn fact, here, have one now!", objectives = "Talk with the Caravan Master at Vulpera Hideaway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54262] = { id = 54262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Brennadam", description = "Your followers have sent a report regarding the mission at Brennadam.\n\nIt details that they were successful in gaining access to a Harvester mount.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission to Brennadam?", completion = "It seems the mission to enhance our outpost at Brennadam was a success. Well done, {name}.\n\nI will send you to oversee the upgrade yourself.", objectives = "Deliver the report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54263] = { id = 54263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outpost Upgrade: Brennadam", description = "The mission at Brennadam was a success. Well done, {name}.\n\nWe now have access to what's rumored to be a very fast Harvester that you are able to ride. Sounds strange to me, but what do I know?\n\nTravel to Brennadam and enquire about this upgrade.", completion = "Well, sure, it don't look like much but hooo-boy when it goes it really goes!\n\nWant to take it for a spin?", objectives = "Talk to Hank Harrison in Brennadam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54265] = { id = 54265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from Azshara", description = "This medallion is inscribed with orders commanding the naga to invade our shores and seize artifacts of power.\n\n<Kojo studies you thoughtfully.>\n\nI've heard tales of a priest who used a horrifying dagger to fight the Burning Legion. It is said this blade... Xal'atath... whispers secrets of the deep. It might be our best chance of uncovering what the naga seek.\n\nI'm told the naga have an altar on an island in Stormsong Valley. If you take Xal'atath there, the dagger may reveal crucial information.", completion = "<You feel a familiar sensation as Xal'atath reaches out to your mind.\n\nA beguiling blend of dread... and delight.>", objectives = "Retrieve Xal'atath and find the Makeshift Altar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54266] = { id = 54266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortar Master Zapfritz" }
quests[54267] = { id = 54267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Attack!" }
quests[54268] = { id = 54268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impulsive Propulsion" }
quests[54269] = { id = 54269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "None Shall Escape", description = "De Alliance are using de Dark Iron's mole machines to transport troops in and out of Zalamar.\n\nWe need dose machines destroyed. We are going to establish Zalamar as our forward base to attack de Alliance's main fleet.\n\nTake out dem machines, den find Rokhan within Zalamar. He be tracking down where de Alliance general be hidin'.", completion = "With dem mole machines destroyed, we be able ta make a base in dis place ta fight de Alliance fleet.", objectives = "Destroy 4 Mole Machines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54270] = { id = 54270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Mirrors", description = "We have reports dat Telaamon,  de Lightforged in charge of dis attack, can create mirror images of himself to strike us down.\n\nTwo Zandalari, Witch Doctor Kejabu and Jo'chunga, have offered to go in and help fight his mirror images. \n\nI want you to ensure dey survive.\n\nEliminating dese strange images should make Telaamon weaker, allowing you and Rokhan to slay him.", progress = "Are de Zandalari safe?", completion = "It be good ta be seein' Jo'chunga and Kejabu again. We gonna need all de help we can get against dis Telaamon.", objectives = "Defeat Telaamon's mirror images within Zalamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54271] = { id = 54271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telaamon's Purge", description = "Telaamon, de Lightbringer leadin' dis assault, be in Hir'eek's cave. He must be thinkin' he can take us all by himself.\n\nWhen he is dead, we be sendin' dis assault force into chaos, allowin' us ta be marchin'  on de Alliance along de shore.\n\nAnd hopefully, we can be findin' de source of de fog and destroyin' it.\n\nDa three of us be ambushin' Telaamon once ya start fightin'. He ain't gettin' outta here alive.", completion = "Telaamon be defeated. We best get movin'.", objectives = "Defeat Telaamon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54272] = { id = 54272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Bots" }
quests[54273] = { id = 54273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Bots" }
quests[54275] = { id = 54275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parting Mists", description = "It be time ta face de main Alliance fleet. Dey be on da beachhead nearby.\n\nI can be feelin' da dark voodoo from dat fog nearby. Princess Talanji be wantin' ta destroy dat mojo as soon as we can.\n\nI can be gettin' us outta dis cave real fast, den we be ridin' with da princess and Rakera ta put an end ta all dis.", completion = "I do not like dis, {name}. We must investigate further.", objectives = "Ride with Princess Talanji and destroy the Alliance fleet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54276] = { id = 54276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in Gnomeregan", description = "Our engineers have reported surges of electric usage in Gnomeregan recently. We need you to investigate what is going in there as soon as possible.\n\nWe made contact with one of the chief engineers in charge of keeping the robots in Gnomeregan under control, and he has offered to assist us in getting inside to see what's going on.", completion = "I don't know how this is possible! What is going on in there?! I don't have time to answer your questions or send you off on trivial tasks, there's work to be done! \n\nOh, you want to go in Gnomeregan and find out what's going on? Why didn't you say so?", objectives = "Find Micro Zoox outside of Gnomeregan in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54280] = { id = 54280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fly Out to Meet Them", description = "De Alliance scum will pay for dis! Our army is moving as fast as it can to defend our city.\n\nRide with Raal to get back to de entrance to our city. We must stop de Alliance!", completion = "We cannot go further, de Alliance are swarming my city!", objectives = "Ride back to Zuldazar with Hexlord Raal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54281] = { id = 54281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombing Ballistae" }
quests[54282] = { id = 54282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Dazar'alor", description = "Zandalar is already under attack! My people are fleeing and de Alliance are infesting my streets.\n\nRakera's scouts say dat Jaina Proudmoore is leading de assault.\n\nShe and her kind will pay for dis brazen assault on my people. \n\nGather your allies and push de Alliance back. We must protect my father and destroy de Alliance!", completion = "To say that this attack was catastrophic would be an understatement. We have lost our major weapon in this war.\n\nYou did manage to give us some victories, though. Mekkatorque is dead, and Jaina Proudmoore badly injured.\n\nGet your rest. Lady Sylvanas has been informed of what has happened and is forming a counterattack as we speak.", objectives = "Defeat Jaina Proudmoore in the Battle of Dazar'alor raid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54284] = { id = 54284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Castaway Point", description = "Your followers have sent a report regarding the mission at Castaway Point.\n\nIt details that they were successful in gaining access to an extremely large cannon.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission to Castaway Point?", completion = "It seems the mission to enhance our outpost at Castaway Point was a success. Well done, {name}.\n\nI will send you to oversee the upgrade yourself.", objectives = "Deliver the report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54287] = { id = 54287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Attack!" }
quests[54288] = { id = 54288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outpost Upgrade: Castaway Point", description = "The mission at Castaway Point was a success. Well done, {name}.\n\nWe now have access to a very large cannon which promises to be a fast way to travel to Tiragarde Sound. Glad that's not how I plan to get around.\n\nTravel to Castaway Point and enquire about this upgrade.", completion = "Ain't she a beauty? I know its unusual, but this baby here can get you quick smart to Tiragarde Sound. \n\nWant to give her a shot?", objectives = "Talk to Dynamite Jack in Castaway Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54295] = { id = 54295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artillery Master Goodwin" }
quests[54298] = { id = 54298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gravity Matters" }
quests[54300] = { id = 54300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Faith", description = "De faithful are among de most revered in Zandalari society. They are an example for others to aspire to. This is not de example we want others to follow.\n\nWe must respond in kind.\n\nPrincess Talanji wishes for us to spare them that will see reason. Do so, if you can find any willing to surrender.\n\nFor de rest, give them a swift death.", completion = "De faithful among us are meant to be de example others must follow. In turn, we must make an example of them when they fail.", objectives = "Subdue 12 angered priests, druids, or prelates in the Terrace of the Chosen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54301] = { id = 54301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talanji's Mercy", description = "I know my priests, {name}. Such an uproar did not appear out of thin air.\n\nThere is much I have to atone for, but I am not yet ruler. I have not had de time to do what is needed for de faithful of Zandalar. That does not mean they deserve to suffer.\n\nGo into de Terrace of de Chosen and find them that refuse to fight. See that they get out safely. I will hold none of them accountable for de actions of others.", progress = "De people of Zandalar are my first priority, {name}.", completion = "It is a weight off my mind. Thank you.", objectives = "Evacuate 10 innocent bystanders in the Terrace of the Chosen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54302] = { id = 54302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Zuldazar", description = "It's time, {name}. We have the Abyssal Scepter, along with confirmation that the bombs placed amongst the Zandalari fleet are still active.\n\nUnfortunately, even with everything at our disposal, we would still lose a frontal assault against the Zandalari empire.\n\nFor that reason, we plan to lure the forces of the Horde and the Zandalari away from the harbor.\n\nMathias Shaw is holding a meeting nearby, and he has requested your presence.", progress = "I take it you and the Lord Admiral were able to send the Horde packing?", completion = "Now you know the gravity of the situation. We must begin.", objectives = "Speak with Mathias Shaw in the garden within Proudmoore Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54303] = { id = 54303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The March to Nazmir", description = "Greetings, {name}. I am Blademaster Telaamon, and I have volunteered to lead this mission against the Horde.\n\nOur forces will be gathering off the coast of Nazmir. Go now and we shall all meet there.\n\nIf all goes according to plan, we will lure the Horde away from Zandalar and bring an end to this war.", completion = "We're all here. Let's begin.", objectives = "Meet Jaina Proudmoore and the Alliance army in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54306] = { id = 54306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Arom's Stand", description = "Your followers have sent a report regarding the mission at Arom's Stand.\n\nIt details that they were successful in gaining access to a blessing from the Order of Embers.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission to Arom's Stand?", completion = "It seems the mission to enhance our outpost at Arom's Stand was a success. Well done, {name}.\n\nI will send you to oversee this yourself.", objectives = "Deliver the report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54307] = { id = 54307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outpost Upgrade: Arom's Stand", description = "The mission at Arom's Stand was a success. Well done, {name}.\n\nWe now have access to a blessing from the Order of Embers.\n\nTravel to Arom's Stand and enquire about this blessing.", completion = "Yes of course, you have done so much for us, the least we can do is grant you our blessing.", objectives = "Talk to Cleric Loriette in Arom's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54308] = { id = 54308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mine Your Business" }
quests[54310] = { id = 54310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repurposing Their Village", description = "Myself and Shaw will provide support for Telaamon's army until our distraction is set up.\n\nFirst, we need to clear the blood trolls out of their nearby village, Zalamar, in order to move our army forward.\n\nThat's where you come in. We need you to assault the blood trolls there to weaken their forces, then our army will arrive.\n\nTelaamon will be on site to help you, meet with him once you've weakened their forces. \n\nI will be here with Shaw ensuring our forces aren't seen.", progress = "We must move, time is of the essence.", completion = "How many did you kill? Hrm... seems as if we are at the same number. Good work.", objectives = "Defeat 12 blood trolls within Zalamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54312] = { id = 54312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fog of War", description = "Do not mind this, I am finishing off this insect. You have bigger matters to handle.\n\nOur army is moving within Zalamar as we speak. But the Horde will know our army's true size without aid.\n\nSpeak with Brother Pike and have him perform the ritual with the Abyssal Scepter to cover Nazmir in a thick fog.\n\nHe claims the illusion will also mimic an entire fleet off the beach. Let us hope he is right.\n\nI will join you once I finish with this stain upon Azeroth.", progress = "We don't have time to discuss this, {name}. We must begin.", completion = "We have our fog, now we have to move.", objectives = "Have Brother Pike use the Abyssal Scepter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54328] = { id = 54328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knight-Captain Joesiph" }
quests[54329] = { id = 54329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: War Resources", progress = "Our forces are gathering for the battle to come. Do you wish to help further our efforts?", completion = "A generous donation. I will let the commander know of your contributions." }
quests[54330] = { id = 54330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Platinum Ore", progress = "Certain ore is harder to come by these days. If you find any platinum in your travels, it would go a long way in helping our cause.", completion = "Your donation will not be forgotten." }
quests[54331] = { id = 54331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Winter's Kiss", progress = "Our herb stocks be runnin' low. Got any ta spare?", completion = "I'll make sure ta put dese ta good use." }
quests[54332] = { id = 54332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Star Moss", progress = "It be better ta be well prepared dan be in short supply. If ya have any star moss ta spare, we'll be makin' good use of it.", completion = "Very generous of ya, {name}." }
quests[54333] = { id = 54333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Storm Silver Ore", progress = "We produce blades and armor for our troops night and day, and such work requires materials. We need ore, all you can spare.", completion = "This should be enough." }
quests[54334] = { id = 54334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Electroshock Mount Motivator", progress = "Our allies need to get to the front lines faster. Any thoughts on how we can accomplish this?", completion = "These should give our allies the boost they need!" }
quests[54335] = { id = 54335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Unstable Temporal Time Shifter", progress = "Our healers are spread thin and we need alternative methods to handle our fallen troops.", completion = "With a donation like this you are truly saving our hide." }
quests[54336] = { id = 54336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: XA-1000 Surface Skimmer", progress = "The enemy believes we will only attack by land. But we shall also flank them by sea.\n\nHave you any crafts that can help with this endeavor?", completion = "Oh yes! This will do quite nicely!" }
quests[54337] = { id = 54337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Umbra Shard", progress = "Battles are won by dose wit powah. Powah comes from witin oneself.\n\nBut enchantments help too and our supplies be runnin' low.", completion = "Dese are hard ta come by, you know?\n\nWe be appreciatin' ya donation to da cause." }
quests[54338] = { id = 54338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Thermo-Accelerated Plague Spreader", progress = "Soldiers rely upon each other in battle. What do say we provide them with a little boost on the battlefield?", completion = "Our enemies will be quite surprised to have to deal with these!" }
quests[54339] = { id = 54339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Potion of Rising Death", progress = "I'd love to get my hands on a few combat potions. Da ya have any to spare?", completion = "Yes. These will do just fine." }
quests[54340] = { id = 54340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Enchant Ring - Seal of Haste", progress = "You be havin' any enchantments for me?", completion = "Dese will do nicely." }
quests[54341] = { id = 54341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Enchant Ring - Seal of Mastery", progress = "Any interesting finds lately?", completion = "Tank you kindly." }
quests[54342] = { id = 54342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Potion of Bursting Blood", progress = "Not everyone is born a courageous warrior, but who says you can't temporarily behave as such?", completion = "Dese will do quite nicely." }
quests[54343] = { id = 54343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Potion of Replenishment", progress = "Years of study have allowed us to produce potions capable of enhancing one's magical regeneration. Have you seen such an item recently? I would die to get my hands on one.", completion = "Fine work." }
quests[54344] = { id = 54344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Crimson Ink", progress = "This particular ink has quite a powerful effect. Perhaps you're able to acquire such an item?", completion = "Yes. This will do." }
quests[54345] = { id = 54345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Contract: The Honorbound", progress = "Have some contracts for me?", completion = "These will ensure that those we hire will be bound by more than just words." }
quests[54346] = { id = 54346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Gold", description = "Our friends here are accepting all kinds of donations on behalf of the war effort, but if ya ask me, no battle was ever won without proper funding. That's right, bub. I'm talking about money! And lots of it.\n\nIf you got it, we need it!", progress = "A {class} like you's surely gotta have a little extra cash in your stash.\n\nWaddaya say? Lemme help lighten your load a bit?", completion = "Ain't nothin' more valuable than sweet, sweet gold.", objectives = "Donate 1000000 Gold to Paymaster Grintooth in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54347] = { id = 54347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Ultramarine Ink", progress = "Our scribes' ink supplies are in short supply. Would you be able to help with this problem?", completion = "You are very kind, {name}. Thank you." }
quests[54348] = { id = 54348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Deep Sea Satin", progress = "If we're going to keep our casters clothed, we'll need to make sure our stockpile is ready.\n\nIf you find yourself swimming in an abundance of deep sea satin I'd be happy to send them along to our stores.", completion = "Our allies will be delighted. Thank you." }
quests[54349] = { id = 54349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Tidespray Linen Bandage", progress = "Bandages go a long way on the battlefield, especially when our healers are spread thin. Do you have any to spare?", completion = "These will help immensely." }
quests[54350] = { id = 54350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Tidespray Linen Net", progress = "If we're going to handle our enemies rushing our allies, we'll need something sturdy to slow them down.\n\nI've heard tailors can produce some fine netting. Would you happen to have any?", completion = "I'll be sure to send these along." }
quests[54351] = { id = 54351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Deep Sea Bandage", progress = "We've started a special stockpile of bandages for scenarios where we'll need a little something extra to keep our allies going. I've added one particular item to the list.\n\nIf you have any to spare I'll make sure they're put to good use.", completion = "I suspect these will tend to many a wound." }
quests[54352] = { id = 54352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Shimmerscale Diving Suit", progress = "Ya know what'll really surprise our enemies? The unexpected.\n\nAnd I know just the thing.", completion = "They're never gonna see us coming!" }
quests[54353] = { id = 54353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Blood-Stained Bone", progress = "Bones are abundant these days, but only within our fallen allies and foes. We need stronger bones, from the beasts of these lands.\n\nHave you come across any in your travels?", completion = "These will do perfectly.", objectives = "Gather 20 Enchant Weapon - Stalwart Navigation for Uma'wi in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54354] = { id = 54354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Shimmerscale Diving Helmet", progress = "I was just about done filling orders for the next shipment then realized I was out of diving helmets!\n\nDo you think you can help me fill the remaining orders?", completion = "Many thanks.", objectives = "Gather 5 Enchant Ring - Seal of Critical Strike for Uma'wi in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54355] = { id = 54355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Mistscale", progress = "Our leatherworking supplies having been running low. If you're able to spare any, it would go a long way in preparing our allies for the battle to come.", completion = "Quite the contribution. Thank you, {name}.", objectives = "Gather 100 Enchant Ring - Seal of Versatility for Uma'wi in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54356] = { id = 54356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Quick Golden Beryl", progress = "Enhancement gems go a long way. If we're to endure the battle, we've got to be prepared.", completion = "Your donation is most appreciated." }
quests[54357] = { id = 54357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Masterful Kubiline", progress = "Have any cut kubiline you would like to donate?", completion = "Very generous of you." }
quests[54358] = { id = 54358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Scarlet Diamond", progress = "A few more gems and the next shipment will be ready.\n\nI'll be here if you find any in your travels.", completion = "Good work. I'll get them loaded into our shipment immediately." }
quests[54359] = { id = 54359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Sand Shifter", progress = "Our food supplies are running low. Would you have any on you to spare for the battle to come?", completion = "I'll make sure these get to our allies. Thank you." }
quests[54360] = { id = 54360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Stringy Loins", progress = "If you can bring me some of those stringy loins, I can get back to business and prepare for the battle to come.", completion = "I will pass these along.\n\nThanks for your donation." }
quests[54361] = { id = 54361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Wild Berry Bread", progress = "A few of those new desserts would be a nice addition to our supply. Bring me a few and I'll be sure they get to where they need to be.", completion = "I knew I could count on you." }
quests[54362] = { id = 54362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Seasoned Steak and Potatoes", progress = "Some of the best meals give our allies a fighting chance. If you come across any, come and see me.", completion = "Don't worry, {name}. I'll make sure these get to our allies." }
quests[54363] = { id = 54363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: War Resources", progress = "We are part of a great effort. Let us stand together in the battle to come.", completion = "Thank you for your contribution." }
quests[54364] = { id = 54364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Star Moss", progress = "There is no such thing as too much star moss. It is better to maintain a strong supply than be left wanting.", completion = "How thoughtful of you.", objectives = "Gather 30 Tidespray Linen for Faella in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54365] = { id = 54365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Storm Silver Ore", progress = "Our miners work their hands down to the bone gathering materials fer us, but they can only find so much. Ye wouldn't happen ta have any spare storm silver, would ye?", completion = "Fantastic! This will get us closer to our goal.", objectives = "Gather 30 Battle Flag: Spirit of Freedom for Faella in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54366] = { id = 54366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Winter's Kiss", progress = "Our winter's kiss supplies are running low.\n\nYou wouldn't happen to be an herbalist? Or know an herbalist? Or have some winter's kiss with you?", completion = "That should put us back in business. Thank you, {name}.", objectives = "Gather 30 Battle Flag: Phalanx Defense for Faella in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54367] = { id = 54367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Platinum Ore", progress = "Ore isn't easy ta come by nowadays and platinum ore is even harder. But if ye have any ta spare, it would go a long way.", completion = "Every bit helps. Many thanks, {name}.", objectives = "Gather 10 Battle Flag: Phalanx Defense for Faella in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54368] = { id = 54368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Unstable Temporal Time Shifter", description = "It's time we snuff out the competition, don't you agree? With your help we can ensure our allies receive the necessary goods and armor to prepare for the battle to come.\n\nLet's make sure our allies are well prepared.", progress = "Our healers are spread thin and we need alternative methods to handle our fallen troops.", completion = "Quite an offering. Thank you.", objectives = "Donate 2 Coarse Leather to Charlane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54369] = { id = 54369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Electroshock Mount Motivator", description = "I'll keep it simple: we need more Shimmerscale!\n\nI apologize for being so forward with you, but there's little time to waste.\n\nIf you happen upon this item throughout your travels I'd be more than happy to put it to good use. Outfitting our allies is of the utmost importance in the battle to come, don't you agree?", progress = "Outfitting our allies is of the utmost importance. This provides us the necessary materials to ensure no one is left lagging behind on the battlefield.", completion = "With your help, our troops will be ready to rush into battle!", objectives = "Donate 2 Shimmerscale to Charlane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54370] = { id = 54370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: XA-1000 Surface Skimmer", description = "Ye look like the kind o' <lad/lass> that ought ta be carryin' loads o' ore around with ya! If my assumption is right about ye, we could use yer help to gather a bit more ore for the war effort.\n\nHave ye any ore ta spare?", progress = "The battle may take to the sea, and we need deployable means of dealing with our enemies.", completion = "By land or sea, our enemies have nowhere to run now. Many thanks.", objectives = "Gather 2 Monelite Ore to Brandal Darkbeard in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54371] = { id = 54371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Thermo-Accelerated Plague Spreader", description = "It's not just our allies we need to protect in the upcoming battle, but our equine friends as well!\n\nCan you lend a hand and ensure our allies receive the best possible armor for the battle ahead?", progress = "Our allies are in need of offensive choices in the battle to come.", completion = "The enemy will never know what him them.", objectives = "Gather 3 Coarse Leather Barding for Charlane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54372] = { id = 54372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Umbra Shard", progress = "Battles are won by those with power. Power comes from within oneself.\n\nBut enchantments help too and our supplies are running low.", completion = "These are hard to come by, you know?\n\nWe appreciate your donation to the cause.", objectives = "Donate 3 Drums of the Maelstrom to Charlane in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54373] = { id = 54373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Enchant Ring - Seal of Haste", progress = "We need more enchantments for our troops!", completion = "These will do nicely.\n\nThank you for your support.", objectives = "Gather 2 Straddling Viridium for Larold Kyne in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54374] = { id = 54374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Potion of Rising Death", progress = "Our combat potions are running low. Any you can spare would be greatly appreciated.", completion = "Splendid.", objectives = "Gather 2 Versatile Kyanite for Larold Kyne in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54375] = { id = 54375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Enchant Ring - Seal of Mastery", progress = "Have you seen any of these lately?", completion = "You're quite the gem, aren't you?", objectives = "Gather 2 Deadly Solstone for Larold Kyne in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54376] = { id = 54376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Potion of Replenishment", progress = "With preparation comes success.", completion = "My thanks.", objectives = "Gather 2 War-Scroll of Battle Shout for Liao in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54377] = { id = 54377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Crimson Ink", description = "Enlightenment guides our path to victory. In battle, we fight as one.\n\nShare your knowledge and skills with me. Generosity is never forgotten.", progress = "Enlightenment presents opportunity for victory.", completion = "Your gift is most appreciated.", objectives = "Gather 20 War-Scroll of Intellect for Liao in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54378] = { id = 54378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Potion of Bursting Blood", progress = "The opportunity for strength and fortitude present themselves when facing difficult situations.", completion = "May preparation guide us, and bravery shine within.", objectives = "Gather 2 War-Scroll of Fortitude for Liao in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54379] = { id = 54379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Contract: 7th Legion", description = "Greetings!\n\nWith the war effort in full swing I'll be your point of contact for herbalism and alchemical donations! It's a pleasure to meet you!\n\nNow, let's see here... Ah, yes. Siren's Pollen. It appears our stockpiles reported a shortage as of late last night. It would be a great help to us all if you were able to donate to our efforts.", progress = "Have some contracts for me?", completion = "These will ensure that those we hire will be bound by more than just words.", objectives = "Gather 3 Siren's Pollen for Chelsea Strand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54380] = { id = 54380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Gold", description = "We've spent a great deal of time and resources preparing for the battle to come. \n\nAs we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. \n\nWould you like to make a donation?", progress = "As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice.\n\nWould you like to make a donation?", completion = "How generous of you, {name}.", objectives = "Donate 1000000 Gold to Paymaster Vauldren in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54381] = { id = 54381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Ultramarine Ink", description = "Greetings, traveler.\n\nI was asked to ensure our food supplies are never left wanting and our fish supplies have been running low lately. Have anything you would care to donate?", progress = "I was asked to ensure our inscription supplies are never left wanting, though lately they have been running low.\n\nHave any ink you would care to donate?", completion = "This will do just fine. I'll be sure our scribes are given an ample supply for the battle to come.", objectives = "Gather 60 Grilled Catfish for Senedras in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54382] = { id = 54382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Deep Sea Satin", description = "Fish--it's what's for dinner! Or so say our supply officers. And this weeks meals are based around one delicious ingredient--catfish.\n\nIf we're going to keep our allies well fed and full of fish we'll need to gather more stock and begin meal preparations soon. \n\nIf you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.", progress = "If we're going to keep our casters clothed, we'll need to make sure our stockpile is ready.\n\nIf you find yourself swimming in an abundance of deep sea satin I'd be happy to send them along to our stores.", completion = "Our allies will be delighted. Thank you.", objectives = "Gather 30 Great Sea Catfish for Senedras in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54383] = { id = 54383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Shimmerscale Diving Suit", description = "Hey there!\n\nTransmission's come down from up top--we need more ammunition! Something with a bit more kick. Something really unexpected!\n\nFrom what I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few I'm sure our munitions officers would be ecstatic!\n\nMaybe they'd even let me keep one to examine!", progress = "I've heard there's a special underwater suit that's crafted by the most experienced of leatherworkers.\n\nIf you were to bring me a few of these I'm sure our aquatic forces would be ecstatic!", completion = "Wow! These are magnificent! The craftsmanship alone is... \n\nApologies, I get carried away sometimes.\n\nTake care!", objectives = "Gather 3 Frost-Laced Ammunition for Norber Togglesprocket in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54384] = { id = 54384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Tidespray Linen Net", description = "Though our ammunition stockpiles are faring well, it's my duty to find additional resources, especially those that are harder to come by.\n\nToday I'm looking for a specific type of ammunition, one with incendiary properties. I could really use your help tracking a few of these down.", progress = "If we're going to handle our enemies rushing our allies, we'll need something sturdy to slow them down.\n\nI've heard tailors can produce some fine netting. Would you happen to have any?", completion = "I'll be sure to send these along.", objectives = "Gather 5 Incendiary Ammunition for Norber Togglesprocket in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54385] = { id = 54385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Tidespray Linen Bandage", progress = "Bandages go a long way on the battlefield, especially when our healers are spread thin. Do you have any to spare?", completion = "Spectacular! These will help immensely." }
quests[54386] = { id = 54386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Deep Sea Bandage", description = "You never know when you'll need to deliver a big bang on the battlefield, if you know what I mean. Luckily we can plan for the unexpected!\n\nWe've begun to store a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. \n\nIf you have any to spare I'll make sure they're put to good use.", progress = "We've started a special stockpile of bandages for scenarios where we'll need a little something extra to keep our allies going. I've added one particular item to the list.\n\nIf you have any to spare I'll make sure they're put to good use.", completion = "I suspect these will tend to many a wound.", objectives = "Gather 10 F.R.I.E.D. for Norber Togglesprocket in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54387] = { id = 54387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Blood-Stained Bone", progress = "I know it's short notice, but I'm trying to find a few more bones to add to our next shipment.", completion = "Nice work! These bones smell... well, they'll work for what we need.", objectives = "Gather 20 Enchant Ring - Seal of Versatility for Mae Wagglewand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54388] = { id = 54388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Shimmerscale Diving Helmet", progress = "I was just about done filling orders for the next shipment then realized I was out of diving helmets!\n\nDo you think you can help me fill the remaining orders?", completion = "Thanks for helping keep things on track. Where would we be without generous people like you?", objectives = "Gather 5 Enchant Ring - Seal of Critical Strike for Mae Wagglewand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54389] = { id = 54389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Mistscale", progress = "I've been able to keep pace with our orders until recently. Now I'm afraid I won't be able to keep up without help.\n\nWould you be willing to donate a few supplies?", completion = "I knew I could count on you.", objectives = "Gather 100 Enchant Weapon - Stalwart Navigation for Mae Wagglewand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54390] = { id = 54390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Masterful Kubiline", description = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air.\n\nIf you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", progress = "Our jewelcrafters work night and day preparing gems for the battle to come.\n\nIf you have any spare cut gems, it would help alleviate their burden.", completion = "I'll get these to our supply officers right away.", objectives = "Gather 20 Seasoned Loins for Senedras in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54391] = { id = 54391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Quick Golden Beryl", description = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air.\n\nIf you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", progress = "Enhancement gems go a long way. If we're to endure the battle, we've got to be prepared.", completion = "These will be adequate.\n\nThank you, {name}.", objectives = "Gather 20 Seasoned Loins for Senedras in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54392] = { id = 54392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Sand Shifter", description = "In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction.\n\nIf yer able ta bring me a few I'll be sure they're put ta good use.", progress = "Our food supplies are running low. Specifically our supply of fish. Would you happen to be a master angler?", completion = "Perfect, this is plenty.", objectives = "Gather 30 Monel-Hardened Stirrups for Brandal Darkbeard in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54393] = { id = 54393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Scarlet Diamond", description = "Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies needin' help, but our beasts of battle as well.\n\nIf ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.", progress = "We have our own jewelcrafters hard at work, adoring armor with their special cuts.\n\nHowever, our supply of raw gems is rather low. Have you any to spare?", completion = "Quite generous of you, {name}. I'll be sure they're put to good use.", objectives = "Gather 20 Monel-Hardened Hoofplates for Brandal Darkbeard in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54394] = { id = 54394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Stringy Loins", description = "One of our latest shipments of alchemical supplies was raided en route to storage. We're scrambling to get our stock back on track, but I'm worried we won't make our quota.\n\nYou wouldn't happen to know where one can acquire additional mana potions, would you?", progress = "Our food stock has been running low trying to keep everyone fed. Do you have any supplies you can spare?", completion = "This is just what I was looking for.", objectives = "Bring 30 Coastal Mana Potions to Chelsea Strand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54395] = { id = 54395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Seasoned Steak and Potatoes", description = "I've received word our allies are looking to stash away a few supplementary items for the battle to come. If you happen to stumble across a few Coastal Healing Potions I'd be more than happy to add them to our stores.", progress = "A hearty meal provides the nourishment our allies deserve.\n\nIf you bring me some freshly seasoned steak and potatoes I would be more than happy to deliver it to our supply officers.", completion = "Mmm...\n\n<Senedras takes in the scent of the food you've brought him.>\n\nThis smells delicious. Thank you, {name}.", objectives = "Gather 40 Coastal Healing Potions for Chelsea Strand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54396] = { id = 54396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkshore Donations: Wild Berry Bread", progress = "Have you heard of this new dessert the chefs are making? I think it's called Wild Berry Bread. You wouldn't happen to have any, would you?", completion = "Thank you for giving us so much.", objectives = "Gather 40 Steelskin Potions for Chelsea Strand in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54402] = { id = 54402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shifting Gears", description = "{name}! The Alliance has made a new request for Gnomeregan's might.\n\nCaptain Sparknozzle wishes for your expert assistance in the matter.\n\nHe'll be waiting for you in New Tinkertown, outside of Gnomeregan.", completion = "The rest of the gnomes I requested arrived shortly before you. Allow me to brief you on the situation.", objectives = "Meet Captain Tread Sparknozzle in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54403] = { id = 54403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tidesage Clarissa" }
quests[54404] = { id = 54404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Machinations", description = "We have some additional support for our plan to deceive the Horde and assault the Blood Gates, but we need your help.\n\nThe Dark Iron dwarves have several mole machines waiting to erupt and supply fresh troops.\n\nI've determined several spots within Zalamar that would be perfect for them to use.\n\nTake this device and plant it in the following areas. It will send a message to the Dark Iron dwarves to erupt from there.\n\nThey will stay safely in their machines until our army arrives.", completion = "Excellent! We are one more step closer to purging the Horde.", objectives = "Mark 3 areas within Zalamar for mole machines to appear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54407] = { id = 54407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lurking in the Swamp", description = "We have Zalamar, and we've got our fog. Now, we have to take the attack to the Horde.\n\nOur goal is to take as much land in Nazmir as possible to make the Horde think our main fleet is here.\n\nThe first target is Zul'jan ruins, one of the Horde's main bases in Nazmir.\n\nWe'll have to make our way through the swamps to our attack position. Meet us there.", completion = "We've made it and still maintain the element of surprise.", objectives = "Meet with Jaina Proudmoore outside of Zul'jan ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54412] = { id = 54412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'jan Deluge", description = "Through the mists is Zul'jan ruins, a major Horde outpost in Nazmir. We need to take it over to help our forces push forward.\n\nThe Horde needs to believe a large Alliance army is here, so we're going to throw everything we've got at taking the ruins.\n\nOur army will charge forward to attack, while you join them using my water elemental.\n\nMeet me outside of the ruins when you're done, we'll need to keep pushing forward.", completion = "Good work, our forces have taken over Zu'jan ruins. We're almost to our main destination.", objectives = "Use Jaina's Water Elemental to clear out Zul'jan Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54414] = { id = 54414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gale's Unrest" }
quests[54415] = { id = 54415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulpera for a Day" }
quests[54416] = { id = 54416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warfront Preparations", description = "We must make our preparations. \n\nReturn to Zandalar immediately and rally our forces. Any contributions to our cause must be made.\n\nGo. We will hold for now.", completion = "Welcome back to Zuldazar. We will rally at your side!", objectives = "Take the portal back to the Port of Zandalar to prepare for the Battle for Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54417] = { id = 54417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showing Our Might", description = "We are within reach of the Blood Gate in Zandalar. Once we take that, the Horde and Zandalari will believe our full invasion has begun.\n\nOur forces have already engaged the Zandalari within the Fallen Outpost. We'll need your help to push them back.\n\nI'll be focusing on finishing off what remains of the Horde and Zandalari back in Zul'jan ruins.", completion = "We've taken Zul'jan ruins, and with your help our army will finish off the remaining Zandalari here.", objectives = "Defeat 12 Zandalari forces within the Fallen Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54418] = { id = 54418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mech of Death", description = "We have reports of a goblin machine causing havoc among our troops up ahead. They call it the A.M.O.D.\n\nIt is a crude machine compared to what the Lightforged have aboard the Vindicaar.\n\nTogether, you and I will bring down this machine. Go, I will await for you near the machine and engage it when you are ready.", completion = "You fought well! It is a shame we must part soon, I would have enjoyed fighting side by side with you.", objectives = "Defeat the A.M.O.D.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54419] = { id = 54419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quelling the Masses", description = "One of my own in de Rastari has seen fit to rile de drudges and guards in de Zocalo.\n\nThey threaten de stability of our empire with this foolishness. If they are angry, we can address it. But this wanton destruction will not stand.\n\nGo down into de market of de Zocalo and bring about calm however you can. Choose de method that works for you.\n\nI care only for de result: Peace, so Talanji can finally be crowned.", completion = "I hope we are not too late to stop this unrest from growing.", objectives = "Subdue 12 rioters in the Zocalo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54421] = { id = 54421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming their Beasts", description = "Our goal is to assault the Blood Gate, but to be blunt, we don't have the force necessary for this.\n\nThat's why we have gnomish technology. The Zandalari have battle beasts, direhorns mounted with powerful weapons.\n\nSeveral of these beasts are resting within the Fallen Outpost. This device, the Re-Discombobulator, will give us control over these animals. \n\nTake this device and use it on these battle beasts. We'll assault the Blood Gates once we have them under our control.", completion = "Good work, these beasts will be imperative to take the Blood Gate.", objectives = "Use the Re-Discombobulator to control 3 battle beasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54424] = { id = 54424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shady Character", description = "Your followers tell of a smuggler of wit and guile, who was able to charm them with stories of lands far and wide.\n\nThough it cost a fair sum to retrieve, they managed to obtain a token which when displayed to the smuggler, will allow the bearer to purchase his wares.", progress = "Do you really think you should be talking to me?", completion = "Well alright then, looks like you check out.\n\nYea I got pets, they aren't easy to come by though, so don't expect me to give them away.", objectives = "Deliver the token to the shady character under the bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54433] = { id = 54433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from Azshara", description = "This medallion is inscribed with orders commanding the naga to invade our shores and seize artifacts of power.\n\n<Kojo studies you thoughtfully.>\n\nI've heard tales of a priest who used a horrifying dagger to fight the Burning Legion. It is said this blade... Xal'atath... whispers secrets of the deep. It might be our best chance of uncovering what the naga seek.\n\nI recently came upon a makeshift naga altar in Atal'Gral. If you take Xal'atath there, the dagger may reveal crucial information.", completion = "<You feel a familiar sensation as Xal'atath reaches out to your mind.\n\nA beguiling blend of dread... and delight.>", objectives = "Retrieve Xal'atath and find the Makeshift Altar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54434] = { id = 54434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidmaster Evenshade" }
quests[54436] = { id = 54436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisp'd Into Shape", description = "We're off to a good start, but we're going to need more wood if we want to win this battle!\n\nThe Horde has set up a lumber mill to the north of Bashal'Aran, past Forlorn Crossing. If we take it, we can stop them from destroying the forest while also getting the wisps to help us out.\n\nIt's a two-for-one!", progress = "We need that additional wood from Cinderfall!", completion = "The wisps will do their part from here!", objectives = "Capture Cinderfall Grove and inspire the wisps to help you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54437] = { id = 54437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Owynn Graddock" }
quests[54438] = { id = 54438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crucible of Storms: Relics of Shadow", description = "Your intention to stop the naga attacks was noble, {name}. But that shadowy dagger tricked you into delivering powerful relics into the hands of a great enemy.\n\nNo doubt those artifacts will be well defended. Gather your allies, {class}, and return to the Crucible of Storms.\n\nDefeat any opponents that stand in your way. Ensure the relics cannot be used against the Alliance.\n\nThe naga cannot be allowed to summon their storm... or to call forth something even worse.", completion = "I am pleased that you defeated N'Zoth's minions, {name}. But I feel in my bones that this danger is far from over.\n\nRemain on your guard, champion. Once an Old God fixes his gaze upon you, dark times are sure to follow.", objectives = "Stop Uu'nat within the Crucible of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
